// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0 && amount <= address(c).balance + 1 ether);

        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;

        bool ok;
        vm.prank(caller);
        try c.withdrawAll(caller) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = address(c).balance;

        if (ok) {
            assertTrue(caller == c.owner());
        }
    }
}
